    jitterTick:()=>updateJitter(performance.now(),true),
    get aimRenderAngle() { return null; },
    targets: GetAllTargets,
    trackPacket,
    aim: Aimbot,
    aimModule,
    loot: LootData,
    diagnostics,
    chat: chatState,
    clipboard: clipboardState,
    copyNickname,
    reconnect,
    observeSocket,
    observeCloseRequest,
    observeDeath,
    highlightMine,
    beginPlay,
    guardPlayCallback,
    guardHandshakeCallback,
    guardHandshakeCallbacks,
    connectionInfo,
    step,
    setSetting,
    openUnderMouse,
